      index += 8;
      continue;
    }

    unsigned int ascii = 0;
    unsigned int continuation = 0;
    unsigned int lead2 = 0;
    unsigned int lead3 = 0;
    unsigned int lead4 = 0;
    unsigned int invalid = 0;

    for (unsigned int lane = 0; lane < 8; ++lane) {
      const unsigned char byte = bytes[index + lane];
      const unsigned int bit = 1u << lane;

      if ((special == SPECIAL_E0 && byte < 0xA0) ||
          (special == SPECIAL_ED && byte >= 0xA0) ||
          (special == SPECIAL_F0 && byte < 0x90) ||
          (special == SPECIAL_F4 && byte > 0x8F)) {
        return false;
