      } else if (byte >= 0xE0 && byte <= 0xEF) {
        lead3 |= bit;
      } else if (byte >= 0xF0 && byte <= 0xF4) {
        lead4 |= bit;
      } else {
        invalid |= bit;
      }

      if (byte == 0xE0) {
        special = SPECIAL_E0;
      } else if (byte == 0xED) {
        special = SPECIAL_ED;
      } else if (byte == 0xF0) {
        special = SPECIAL_F0;
      } else if (byte == 0xF4) {
